import {defaults,calculate,products,processingProjection,dateAt,outcomes} from './model.mjs';
import {vanillaPack} from './data/vanilla.mjs';
import {cooking} from './data/cooking.mjs';
import {createRegistry,validatePack,groups,seasonNames} from './registry.mjs';
import {escape as esc,dateLabel,profitChart,cropCalendar} from './charts.mjs';
const $=s=>document.querySelector(s),fmt=(v,d=1)=>Number(v).toLocaleString('ru-RU',{maximumFractionDigits:d}),money=v=>`${fmt(v)} g`;
const STORE='farmsolver-v2';let state={...defaults},packs=[],catalog=[],edits={},view='compare',selected=null,productChoice='';
let filters={season:'scenario',regrow:'all',group:'all',mod:'all',available:false,query:''},sort={key:'total',direction:-1};
try{const data=JSON.parse(localStorage.getItem(STORE));if(data){state={...defaults,...data.state};packs=(data.packs||[]).filter(p=>{try{return p.id!=='vanilla'&&validatePack(p)}catch{return false}});edits=data.edits||{}}}catch{}
function rebuild(){catalog=createRegistry([vanillaPack,...packs]);for(const c of catalog)if(edits[c.id])Object.assign(c,edits[c.id]);$('#nav-count').textContent=catalog.length;$('#catalog-count').textContent=`${catalog.length} видов семян · ${packs.length+1} наборов`;$('#filter-mod').innerHTML='<option value="all">Все наборы</option>'+[vanillaPack,...packs].map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');$('#filter-mod').value=filters.mod}
function persist(){try{localStorage.setItem(STORE,JSON.stringify({state,packs,edits}));$('#save-state').textContent='Сохранено в браузере'}catch{$('#save-state').textContent='Не удалось сохранить: хранилище заполнено'}}
function sync(){for(const k of Object.keys(defaults)){const e=$('#'+k);if(!e)continue;if(e.type==='checkbox')e.checked=state[k];else e.value=state[k]}}
const picture=(c,cls='item-image')=>c.image?`<img class="${cls}" src="${esc(c.image)}" alt="" loading="lazy">`:`<span class="${cls} missing-image">${esc(c.name.slice(0,2))}</span>`;
const calc=c=>calculate(c,state,catalog),allRows=()=>catalog.map(c=>({c,r:calc(c)}));
function filtered(){return allRows().filter(({c,r})=>{const season=filters.season==='scenario'?state.season:filters.season;return(season==='all'||c.seasons.includes(season))&&(filters.regrow==='all'||(filters.regrow==='yes'?c.regrow>0:!c.regrow))&&(filters.group==='all'||c.group===filters.group)&&(filters.mod==='all'||c.mod===filters.mod)&&(!filters.available||r.eligible)&&`${c.name} ${c.en||''}`.toLowerCase().includes(filters.query.toLowerCase())})}
function best(){return filtered().filter(x=>x.r.eligible&&x.r.plots>0&&x.r.total>0).sort((a,b)=>b.r.total-a.r.total)[0]}
function renderStats(){const b=best();$('#stats').innerHTML=`<div class="stat winner"><div class="stat-label">ЛУЧШИЙ МОНОПОСЕВ · СРЕДИ ОТОБРАННЫХ</div><div class="stat-value">${b?esc(b.c.name):'Нет выгодных посадок'}</div><div class="stat-sub">${b?`${b.r.plots} посадочных единиц · ${b.r.dates.length} сборов`:'Измени параметры или фильтры'}</div>${b?picture(b.c,'stat-item'):''}</div><div class="stat"><div class="stat-label">ЧИСТАЯ ПРИБЫЛЬ УЧАСТКА</div><div class="stat-value">${money(b?.r.total||0)}</div><div class="stat-sub">продажа сырья, после стоимости семян</div></div><div class="stat"><div class="stat-label">ВЛОЖЕНИЯ В СЕМЕНА</div><div class="stat-value">${money(b?.r.investment||0)}</div><div class="stat-sub">из ${money(state.budget)} на весь период</div></div>`}
const titles={compare:['Сравнение семян','Календарь и графики — в карточке каждой культуры.'],calendar:['Календарь урожая','Рост и сбор по выбранному сценарию.'],products:['Производные продукты','Цена результата, выход, время и добавленная стоимость сырья.'],packs:['Наборы модов','Подключение культур через наборы данных.'],method:['Модель расчёта','Исходные данные, формулы и границы прогноза.']};
function render(){renderStats();$('#crumb').textContent=titles[view][0];$('#results-heading').textContent=titles[view][0];$('#results-subtitle').textContent=titles[view][1];$('#catalog-filters').hidden=['method','packs'].includes(view);document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.getAttribute('role')==='tab')b.setAttribute('aria-selected',String(b.dataset.view===view))});({compare:renderTable,calendar:renderCalendar,products:renderProducts,packs:renderPacks,method:renderMethod})[view]();document.querySelectorAll('[data-crop]').forEach(b=>b.onclick=()=>openDetail(b.dataset.crop));}
function renderTable(){const b=best(),rows=filtered();rows.sort((a,b)=>{const eligible=Number(b.r.eligible)-Number(a.r.eligible);if(eligible)return eligible;return sort.direction*(sort.key==='name'?a.c.name.localeCompare(b.c.name,'ru'):a.r[sort.key]-b.r[sort.key])});const headers=[['name','Культура / семена'],[null,'Сезоны'],[null,'Рост / повтор'],[null,'Сборы'],['profit','Прибыль / ед.'],[null,'Единиц'],['total','Прибыль участка']];$('#view').innerHTML=`<div class="table-scroll"><table><thead><tr>${headers.map(([key,title])=>`<th>${key?`<button data-sort="${key}">${title} ${sort.key===key?(sort.direction<0?'↓':'↑'):'↕'}</button>`:title}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map(({c,r})=>`<tr class="${!r.eligible?'unavailable':''} ${b?.c.id===c.id?'table-best':''}"><td><button class="row-button" data-crop="${esc(c.id)}"><span class="crop-cell"><span class="crop-emoji">${picture(c)}</span><span><span class="crop-name">${esc(c.name)}</span>${b?.c.id===c.id?'<span class="tag">ВЫБОР</span>':''}<span class="crop-source">${esc(c.source)} · ${esc(groups[c.group])}</span>${c.mod!=='vanilla'?`<span class="tag muted">${esc(c.modName)}</span>`:''}</span></span></button></td><td><span class="season-pills">${c.seasons.map(s=>`<span title="${seasonNames[s]}" class="season-pill ${s}">${{spring:'В',summer:'Л',fall:'О',winter:'З'}[s]}</span>`).join('')}</span><div class="secondary">${money(c.seed)} / семя</div></td><td>${c.stochastic?'Случайный':r.grow+' д.'}<div class="secondary">${c.regrow?'↻ '+c.regrow+' д.':'один сбор'}</div></td><td>${r.variants?'варианты':r.dates.length}<div class="secondary">${r.dates.length?`первый: ${dateAt(r.dates[0],state).day} ${seasonNames[dateAt(r.dates[0],state).season].toLowerCase()}`:'нет в периоде'}</div></td><td class="${r.profit<0?'negative':'profit'}">${money(r.profit)}<div class="secondary">${r.variants?'ожидание · 1 партия':money(r.daily)+' / день'}</div></td><td>${r.plots}<div class="secondary">${c.footprint?c.footprint+' клеток / дерево':'по 1 клетке'}</div></td><td class="${r.total<0?'negative':'profit'}">${r.eligible?money(r.total):'—'}<div class="secondary reason">${r.eligible?'семена: '+money(r.investment):esc(r.reasons[0])}</div></td><td><button class="detail-arrow" data-crop="${esc(c.id)}" aria-label="Карточка: ${esc(c.name)}">↗</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">Культуры не найдены. Измени фильтры.</div>'}</div><div class="table-footer"><span>${rows.length} из ${catalog.length} записей</span><span>Прибыль / ед. — на клетку, куст или дерево</span></div>`;document.querySelectorAll('[data-sort]').forEach(e=>e.onclick=()=>{sort=e.dataset.sort===sort.key?{...sort,direction:-sort.direction}:{key:e.dataset.sort,direction:-1};render()})}
function renderCalendar(){const rows=filtered(),end=state.horizon*28;$('#view').innerHTML=`<div class="table-scroll"><div class="calendar" style="min-width:${Math.max(800,end*25+180)}px"><div class="cal-row" style="grid-template-columns:170px repeat(${end},1fr)"><strong>Период расчёта</strong>${Array.from({length:end},(_,i)=>`<span class="cal-day" title="${esc(dateLabel(i+1,state))}">${dateAt(i+1,state).day}</span>`).join('')}</div>${rows.map(({c,r})=>`<div class="cal-row ${r.eligible?'':'unavailable'}" style="grid-template-columns:170px repeat(${end},1fr)"><button class="row-button cal-name" data-crop="${esc(c.id)}">${picture(c,'tiny-image')}${esc(c.name)}</button>${Array.from({length:end},(_,i)=>{const d=i+1,harvest=r.dates.includes(d),growth=d>=r.start&&d<=(r.dates.at(-1)||r.start+r.grow);return `<span title="${esc(dateLabel(d,state))}${harvest?' · сбор':''}" class="cal-cell ${harvest?'harvest':growth?'growing':''}">${harvest?'✓':''}</span>`}).join('')}</div>`).join('')}<div class="cal-legend">✓ Сбор · светло-зелёный — рост · бледные строки — вне сценария. Для смесей отмечены возможные даты первого сбора.</div></div></div>`}
function renderProducts(){const list=filtered().flatMap(({c})=>{const variants=outcomes(c,state,catalog);return variants?variants.flatMap(o=>products(o,state).map(p=>({c,p,variant:o.name}))):products(c,state).map(p=>({c,p}))});$('#view').innerHTML=`<div class="product-intro">P — базовая цена сырья. Качество сырья не повышает цену переработки. Фиксированные игровые рецепты отмечены отдельно.</div><div class="table-scroll"><table><thead><tr><th>Сырьё → продукт</th><th>Рецепт</th><th>Цена / шт.</th><th>На 1 сырьё</th><th>Добавленная стоимость</th><th>Время</th></tr></thead><tbody>${list.map(({c,p,variant})=>`<tr><td><button class="row-button product-link" data-crop="${esc(c.id)}">${p.image?`<img class="tiny-image" src="${esc(p.image)}" alt="">`:picture(c,'tiny-image')}<span>${esc(p.name)}<span class="crop-source">${esc(c.name)}${variant?' · '+esc(variant):''}</span></span></button></td><td><span class="recipe-formula">${esc(p.formula)}</span><div class="secondary">${p.input} сырья → ${p.output} продукта${p.nonconsuming?' · цветок сохраняется':''}</div></td><td class="profit">${money(p.price)}</td><td>${p.nonconsuming?'—':money(p.perInput)}</td><td>${p.nonconsuming||p.id?.startsWith('mead')?'отдельная цепочка':money(p.perInput-c.base)}</td><td>${p.minutes?fmt(p.minutes/1600,2)+' д.':'кухня'}${p.ageDays?`<div class="secondary">+ ${p.ageDays} д. выдержки</div>`:''}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${list.length} вариантов переработки</span><span>Кулинария и возврат семян — в карточках культур</span></div>`}
function openDetail(id){selected=id;productChoice='';renderDetail();$('#detail').showModal();$('#detail').scrollTop=0}
function renderDetail(){const c=catalog.find(c=>c.id===selected);if(!c)return;const r=calc(c),pp=products(c,state),choices=pp.filter(p=>!p.nonconsuming&&!p.id?.startsWith('mead')),p=choices.find(p=>p.id===productChoice)||choices[0],projection=p?processingProjection(c,r,p):null;
 $('#detail-content').innerHTML=`<div class="detail-heading">${picture(c,'detail-image')}<div><h2 id="detail-title" class="detail-title">${esc(c.name)}</h2><p class="detail-note">${esc(c.source)} · ${esc(c.modName)} · ${esc(groups[c.group])}</p></div>${c.seedImage?`<div class="seed-info"><img src="${esc(c.seedImage)}" alt="Семена"><span>${money(c.seed)} / семя</span></div>`:''}</div>${r.reasons.length?`<div class="detail-alert">Справочный расчёт вне текущего сценария: ${esc(r.reasons.join(' · '))}</div>`:''}${c.note?`<p class="detail-note">${esc(c.note)}</p>`:''}
 <div class="detail-metrics"><div><span>Выручка / ед.</span><b>${money(r.revenue)}</b></div><div><span>Семена / ед.</span><b>${money(r.cost)}</b></div><div><span>Чистая прибыль / ед.</span><b class="${r.profit<0?'negative':'profit'}">${money(r.profit)}</b></div><div><span>Прибыль участка · ${r.plots} ед.</span><b>${money(r.total)}</b></div></div>
 <section class="detail-section"><div class="detail-section-head"><h3>Накопленная прибыль</h3><label>Сравнить с <select id="chart-product">${choices.length?choices.map(o=>`<option value="${esc(o.id)}" ${p?.id===o.id?'selected':''}>${esc(o.name)}</option>`).join(''):'<option>Нет переработки</option>'}</select></label></div>${profitChart(r.series,projection?.series,state)}<div class="chart-legend"><span><i class="line-key"></i>Продажа сырья · на 1 ед.</span>${projection?'<span><i class="line-key potential"></i>Потенциал переработки · на 1 ед.</span>':''}</div><p class="detail-note">${projection?'Пунктир — стоимость продукции из собранного к этому дню сырья, а не деньги к этому дню. Время обработки, число машин и выдержка сдвигают получение денег; их график пока не моделируется. Остаток неполной партии продаётся сырым в конце периода. При среднем случайном урожае потенциал партий является приближением.':'График показывает выручку и затраты по дням. Для случайных смесей — математическое ожидание одной начальной партии.'}</p><details><summary>Проверить значения по дням</summary><div class="table-scroll daily-table"><table><thead><tr><th>День</th><th>Семена</th><th>Выручка</th><th>Баланс</th>${projection?'<th>Потенциал переработки</th>':''}</tr></thead><tbody>${r.series.map((e,i)=>`<tr><td>${esc(dateLabel(e.day,state))}</td><td>${money(e.expense)}</td><td>${money(e.revenue)}</td><td>${money(e.profit)}</td>${projection?`<td>${money(projection.series[i].profit)}</td>`:''}</tr>`).join('')}</tbody></table></div></details></section>
 <section class="detail-section"><h3>Календарь роста и сбора</h3>${cropCalendar(c,r,state)}<p class="detail-note">${r.variants?'Смесь: указаны возможные даты; из одного семени получается один случайный вариант. Повторные посевы смеси не моделируются.':c.stochastic?'Рост из семени случаен. Точные даты сбора доступны только в сценарии взрослого дерева.':c.group==='fruit-tree'?'Дерево растёт 28 дней в любом сезоне, затем даёт плод ежедневно в сезон плодоношения. На дерево резервируется 9 клеток.':c.tea?'Чай даёт листья с 22 по 28 число после созревания куста.':`Первый рост ${r.grow} д.${c.regrow?' · Повторный сбор через '+c.regrow+' д.':' · Повторная посадка в день сбора.'}`}</p></section>
 <section class="detail-section"><h3>Производные и цепочки</h3>${renderDetailProducts(c,r,pp)}${renderVariants(c,r)}${renderSeedMaker(c)}${renderCooking(c)}</section>
 <details class="edit-facts"><summary>Исходные данные · изменить</summary><div class="edit-grid">${[['seed','Цена семян, g'],['base','Базовая цена урожая, g'],['grow','Первый рост, дней'],['regrow','Повторный рост, дней'],...(c.stock!=null?[['stock','Запас семян, шт.']]:[])].map(([key,label])=>`<label>${label}<input type="number" data-edit="${key}" min="${key==='grow'&&!c.stochastic?1:0}" max="100000" value="${c[key]}"></label>`).join('')}</div><button class="outline-button" id="reset-facts">Вернуть игровые данные</button><p class="detail-note">Правки влияют на все расчёты и сохраняются только в этом браузере.</p></details>`;
 $('#chart-product').onchange=e=>{productChoice=e.target.value;renderDetail()};document.querySelectorAll('[data-edit]').forEach(e=>e.onchange=()=>{const k=e.dataset.edit,min=k==='grow'&&!c.stochastic?1:0,v=Math.max(min,Math.min(100000,Math.floor(Number(e.value)||0)));edits[c.id]={...edits[c.id],[k]:v};rebuild();persist();render();renderDetail()});$('#reset-facts').onclick=()=>{delete edits[c.id];rebuild();persist();render();renderDetail()};
}
function renderDetailProducts(c,r,pp){if(c.type==='mix')return '<p class="detail-note">Варианты урожая и их производные показаны ниже.</p>';return pp.length?`<div class="product-cards">${pp.map(p=>{const projection=processingProjection(c,r,p);return `<article class="product-card"><div class="product-card-head">${p.image?`<img class="tiny-image" src="${esc(p.image)}" alt="">`:''}<h4>${esc(p.name)}</h4></div><b>${money(p.price)} <small>/ шт.</small></b><code>${esc(p.formula)}</code><div class="detail-note">${p.input} сырья → ${p.output} шт. · ${p.minutes?fmt(p.minutes/1600,2)+' игровых д.':'кухня'}${p.ageDays?' + '+p.ageDays+' д. выдержки':''}<br>${projection?`Из урожая 1 ед.: ${fmt(projection.units)} шт., остаток ${fmt(projection.leftover)} сырья.<br>Потенциальная прибыль: <strong>${money(projection.profit)}</strong>.`:''}</div>${p.note?`<p class="detail-note">${esc(p.note)}</p>`:''}</article>`}).join('')}</div>`:'<p class="detail-note">У этого урожая нет прямой пищевой переработки в банке, бочонке или сушилке.</p>'}
function renderVariants(c,r){if(!r.variants)return '';const sum=r.variants.reduce((a,v)=>a+v.weight,0);return `<h4>Возможный урожай смеси</h4><div class="variant-grid">${r.variants.map(v=>`<article class="variant-card">${picture(v.o,'tiny-image')}<b>${esc(catalog.find(x=>x.itemId===v.o.itemId)?.name||v.o.name)}</b><span>${fmt(v.weight/sum*100)}% · ${money(v.o.base)}</span><small>${v.date?dateLabel(v.date,state):'не успеет созреть'}</small><div>${products(v.o,state).map(p=>`<p>${esc(p.name)}: ${money(p.price)} <small>${esc(p.formula)}</small></p>`).join('')||'Нет пищевой переработки'}</div></article>`).join('')}</div>`}
function renderSeedMaker(c){const banned=c.group!=='crop'||['vanilla:coffee-bean','vanilla:fiber'].includes(c.id);if(banned)return '';return `<details class="recipe-details"><summary>Возврат в семена</summary><p>Экстрактор семян: в среднем 1,9502 семени этой культуры с 1 урожая (97,51% × средние 2). Ещё 1,99% — смешанные, 0,5% — древние семена. Это ожидание, не гарантированный выход.</p><p>Цена продажи семени: ${money(c.seedSell||0)}. Экономия на покупке: ${money(1.9502*c.seed)} на 1 сырьё при наличии нужного магазина. Размножение не включено в бюджет и календарь.</p>${c.id==='vanilla:sunflower'?'<p>При сборе возвращается 0–2 семени. Масло из семени: фиксированные 100g, 3200 игровых минут. Повторное использование возвращённых семян не включено в расчёт.</p>':''}</details>`}
function renderCooking(c){const intermediates={'vanilla:wheat':['246'],'vanilla:beet':['245'],'vanilla:corn':['247'],'vanilla:sunflower':['247'],'vanilla:unmilled-rice':['423'],'vanilla:coffee-bean':['395']};const ids=[c.itemId,...(c.outcomes||[]).map(o=>o.itemId),...(intermediates[c.id]||[])],recipes=cooking.filter(r=>r.ingredients.some(i=>ids.includes(i.id)));if(!recipes.length)return '';const itemName=i=>catalog.find(o=>o.itemId===i.id)?.name||i.name;return `<details class="recipe-details"><summary>Кулинарные рецепты · ${recipes.length}</summary><p>У блюд фиксированная игровая цена. Себестоимость ниже — упущенная выручка ингредиентов обычного качества; остальные ингредиенты тоже нужны.</p><div class="table-scroll"><table><thead><tr><th>Блюдо</th><th>Ингредиенты</th><th>Выручка / рецепт</th><th>Стоимость сырья</th></tr></thead><tbody>${recipes.map(r=>{const cost=r.ingredients.some(i=>i.base==null)?null:r.ingredients.reduce((a,i)=>{const cat=catalog.find(c=>c.itemId===i.id);return a+(cat?.base??i.base)*i.amount},0);return `<tr><td><span class="product-link">${r.image?`<img class="tiny-image" src="${esc(r.image)}" alt="">`:''}${esc(r.name)} × ${r.output}</span></td><td class="ingredients">${r.ingredients.map(i=>esc(itemName(i))+' × '+i.amount).join(', ')}</td><td>${money(r.price*r.output)}</td><td>${cost==null?'Зависит от выбора категории':money(cost)}</td></tr>`}).join('')}</tbody></table></div></details>`}
function renderPacks(){$('#view').innerHTML=`<div class="packs-view"><div class="pack-actions"><button class="solid-button" id="import-pack">+ Подключить JSON-набор</button><a class="outline-button" href="packs/example.json" download>↓ Пример набора</a><a class="text-button" href="packs/schema.json" target="_blank">Формат данных ↗</a><input type="file" id="pack-file" accept=".json,application/json" hidden></div><p class="detail-note">Наборы хранятся в этом браузере. Файлы модов автоматически не сканируются. Можно подключать несколько наборов с разными идентификаторами.</p>${[vanillaPack,...packs].map(p=>`<article class="pack-row"><div><h3>${esc(p.name)} <small>${esc(p.version||'')}</small></h3><p>${esc(p.id)} · ${p.crops.length} видов семян</p></div>${p.id==='vanilla'?'<span class="tag">БАЗОВАЯ ИГРА</span>':`<button class="outline-button" data-remove-pack="${esc(p.id)}">Отключить</button>`}</article>`).join('')}<div id="pack-error" role="alert"></div></div>`;$('#import-pack').onclick=()=>$('#pack-file').click();$('#pack-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('Максимальный размер набора — 2 МБ.');const p=JSON.parse(await file.text());validatePack(p);if(p.id==='vanilla'||packs.some(x=>x.id===p.id))throw Error('Набор с таким id уже подключён.');createRegistry([vanillaPack,...packs,p]);packs.push(p);rebuild();persist();render();toast('Подключён набор: '+p.name)}catch(err){$('#pack-error').textContent=err.message}};document.querySelectorAll('[data-remove-pack]').forEach(e=>e.onclick=()=>{packs=packs.filter(p=>p.id!==e.dataset.removePack);if(filters.mod===e.dataset.removePack)filters.mod='all';rebuild();persist();render()})}
function renderMethod(){$('#view').innerHTML=`<article class="method"><h3>Исходные факты и вычисляемые значения</h3><p>Каждый набор содержит базовые цены, сроки роста, сезоны, тип урожая, выход за сбор и ограничения доступа. Прибыль, производные цены, графики и календарь вычисляются при изменении сценария. Фиксированные цены кофе, масла, блюд и других специальных рецептов — отдельные правила игры; они не выводятся из стоимости растения.</p><h3>Посадки и бюджет</h3><p>День посадки не считается днём роста. Сбор и повторный посев выполняются в один день. На границе сезонов культура погибает, если новый сезон не поддерживается; теплица и остров снимают сезонные ограничения. Кактус требует помещения. Клубника в первую весну ждёт 13-го числа; позднее предполагается запас семян. Семена всего периода резервируются в бюджете сразу.</p><p><code>затраты единицы = семена × число посадок</code><br><code>единицы = min(площадь / размер, бюджет / затраты, запас / посадки)</code> с округлением вниз.<br><code>прибыль = выручка − семена</code>. Деньги от урожая не реинвестируются. Плодовое дерево занимает в модели 9 клеток; готовые деревья и кусты не требуют новых семян. Их прежняя стоимость считается уже понесённой.</p><h3>Рост и урожай</h3><p>Полив и сбор ежедневные. Качество задаётся вручную и не прогнозируется по навыку. Дополнительные плоды, кроме среднего картофеля, игнорируются: черника даёт 3, клюква 2, кофе 4. Волокно — средние 5,5. Для многоплодных культур качество в модели применяется ко всему урожаю; в игре удобрения влияют на первый плод. Случайные потери, гигантские культуры, труд и материалы изготовления семян не включены.</p><p>Смеси семян — одна начальная партия с вероятностями исходов. Повторные посевы и повторные сборы выпавшего варианта в смеси не включены. Рост лесных деревьев случайный: точные доходы показаны только для уже взрослых деревьев с экстрактором. Грибное дерево и мшистое семя имеют упрощённый сценарий, указанный в карточке. Трава включена в каталог, но не ранжируется по финансовому урожаю.</p><h3>Производные продукты</h3><p>Джем / соленья: <code>2P + 50</code>; вино: <code>3P</code>; сок: <code>⌊2,25P⌋</code>; сушёные фрукты / грибы: <code>⌊7,5P + 25⌋</code> за 5 сырья. Цветочный мёд: <code>100 + 2P</code>, цветок не расходуется. Выдержка и Ремесленник применяются поверх базового рецепта с округлением вниз. Масло и кофе бонус Ремесленника не получают. Для специальных рецептов хранится именно правило, а не таблица готовых цен для каждой культуры.</p><p>Пунктир графика — потенциал переработки урожая, не календарь производства. Число машин, расходы на оборудование, время обработки и выдержка не участвуют в денежном потоке. Неполная партия продаётся сырой в конце периода. Экстрактор семян и рецепты кухни показаны отдельно и не увеличивают основной итог.</p><h3>Моды</h3><p>Версионированные JSON-наборы добавляют культуры с пространством имён <code>mod-id:crop-id</code>. Проверяются идентификаторы, числовые поля и сезоны. Пользовательские рецепты задаются коэффициентами либо фиксированным правилом; исполняемый код в наборах не поддерживается. Отбор по моду, сезону, категории и повторному сбору работает для любых подключённых наборов.</p><h3>Источники</h3><p><a href="https://stardewvalleywiki.com/Crops" target="_blank" rel="noreferrer">Культуры</a> · <a href="https://stardewvalleywiki.com/Artisan_Goods" target="_blank" rel="noreferrer">Переработка</a> · <a href="https://stardewvalleywiki.com/Seed_Maker" target="_blank" rel="noreferrer">Экстрактор семян</a> · <a href="https://stardewvalleywiki.com/Fruit_Trees" target="_blank" rel="noreferrer">Деревья</a> · <a href="https://github.com/juliaramosguedes/stardew-data" target="_blank" rel="noreferrer">Извлечённые игровые факты и спрайты 1.6.15</a>. Готовые расчёты прибыли из источников не используются. Спрайты и игровые материалы © ConcernedApe. Проверено 7 ноября 2026.</p></article>`}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4000)}
document.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>{view=e.dataset.view;render()});
for(const key of Object.keys(defaults)){const e=$('#'+key);if(e)e.onchange=()=>{state[key]=e.type==='checkbox'?e.checked:e.tagName==='SELECT'?(typeof defaults[key]==='number'?Number(e.value):e.value):Math.max(Number(e.min),Math.min(Number(e.max),Math.floor(Number(e.value)||Number(e.min))));sync();persist();render()}}
for(const key of ['season','regrow','group','mod'])$('#filter-'+key).onchange=e=>{filters[key]=e.target.value;render()};$('#filter-available').onchange=e=>{filters.available=e.target.checked;render()};$('#search').oninput=e=>{filters.query=e.target.value;render()};
$('#filter-group').innerHTML+=[...Object.entries(groups)].map(([id,n])=>`<option value="${id}">${n}</option>`).join('');
$('#close-detail').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
$('#assumptions').onclick=()=>{view='method';render()};$('#reset').onclick=()=>{state={...defaults};sync();persist();render();toast('Параметры сценария сброшены. Правки культур можно сбросить в их карточках.')};
$('#export').onclick=()=>{const rows=[['Культура','Мод','Сезоны','Повторный сбор','Доступна','Ограничения','Семена','Базовая цена','Сборы','Прибыль единицы','Единиц','Прибыль участка'],...filtered().map(({c,r})=>[c.name,c.mod,c.seasons.join('/'),c.regrow,r.eligible,r.reasons.join('/'),c.seed,c.base,r.dates.map(d=>dateLabel(d,state)).join('/'),r.profit,r.plots,r.total])];const blob=new Blob(['\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='farmsolver.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
rebuild();sync();render();
